import { Sound } from '@game-studio/asset-manager';
import EventEmitter from 'eventemitter3';
import { logAudioError } from './internal';
import { ISoundInstanceOptions } from './types';

interface ISoundInstanceEvents {
    play: () => void;
    volume: (volume: number) => void;
    stop: () => void;
    seek: (duration: number) => void;
    rate: (rate: number) => void;
    pause: () => void;
    mute: (isMuted: boolean) => void;
    fade: (volume: number) => void;
    end: () => void;
    dispose: (id: number) => void;
}

export class SoundInstance extends EventEmitter<ISoundInstanceEvents> {

    protected disposed: boolean = false;
    public get isDisposed(): boolean {
        return this.disposed;
    }
    protected delayTimeoutId?: number = undefined;
    public readonly sprite?: string;
    protected isMuted: boolean = false;
    protected mVolume: number = 1;
    protected categoryVolume: number = 1;
    protected categoryMute: boolean = false;
    public readonly category: string;

    public constructor(public readonly sound: Sound, public readonly id: number, options: ISoundInstanceOptions) {
        super();
        this.categoryVolume = options.categoryVolume;
        this.categoryMute = options.categoryMute;
        this.sprite = options.sprite;
        this.category = options.category;
        this.loop = options.loop ?? false;
        this.rate = options.rate ?? 1;
        this.mVolume = options.volume ?? sound.volume(id) as number;
        this.updateVolume();
        this.setupHowlListeners();
        const isDelayed = options.delayInMs && options.delayInMs > 0;
        if (isDelayed) {
            this.pause();
            this.delayPlay(options.delayInMs!);
        }
        this.mute = !!options.muted;
        this.builtInCleanup();
        this.seek = options.seek ?? options.start ?? 0;
    }

    protected builtInCleanup(): void {
        this.addListener('end', () => {
            if (!this.loop) {
                this.dispose();
            }
        });
        this.addListener('stop', () => {
            this.dispose();
        });
    }

    public setCategoryVolume(categoryVolume: number): void {
        if (!this.isValidInstance()) {
            return;
        }
        this.categoryVolume = categoryVolume;
        this.updateVolume();
    }

    public setCategoryMute(value: boolean): void {
        this.categoryMute = value;
        this.updateVolume();
    }

    public set mute(value: boolean) {
        if (!this.isValidInstance()) {
            return;
        }

        if (this.isMuted !== value) {
            this.isMuted = value;
            this.volume = this.mVolume;
            this.emit('mute', value);
        }
    }
    public get mute(): boolean {
        return this.isMuted;
    }

    public get duration(): number {
        if (!this.isValidInstance()) {
            return 0;
        }
        return this.sound.duration(this.id);
    }

    protected get soundStart(): number {
        if (!!this.sprite) {
            return this.sound.sprites[this.sprite][0] * 0.001;
        } else {
            return 0;
        }
    }

    public get progress(): number {
        if (!this.isValidInstance()) {
            return 0;
        }
        return Math.max(Math.min(this.seek / this.duration, 1), 0);
    }
    public set progress(value: number) {
        if (!this.isValidInstance()) {
            return;
        }
        value = Math.max(Math.min(value, 1), 0);
        this.seek = value * this.duration;
    }

    protected updateVolume(): void {
        if (this.isDisposed) {
            //volume setting is harmless so crack on
            return;
        }
        if (!this.isMuted && !this.categoryMute) {
            this.sound.volume(this.mVolume * this.categoryVolume, this.id);
        } else {
            this.sound.volume(0, this.id);
        }
    }

    public set volume(value: number) {
        this.mVolume = value;
        this.updateVolume();
    }
    public get volume(): number {
        this.isValidInstance();
        return this.mVolume;
    }
    public get realVolume(): number {
        return (this.mute || this.categoryMute) ? 0 : this.mVolume * this.categoryVolume;
    }

    public set rate(value: number) {
        if (!this.isValidInstance()) {
            return;
        }
        this.sound.rate(value, this.id);
    }
    public get rate(): number {
        if (!this.isValidInstance()) {
            return 1;
        }
        return this.sound.rate(this.id);
    }

    public set seek(value: number) {
        if (!this.isValidInstance()) {
            return;
        }
        const seekValue = this.loop ? Math.mod(value, this.duration) : Math.max(0, value);
        if (!this.loop && seekValue >= this.duration) {
            this.dispose();
            return;
        }
        const seekingTo = this.soundStart + seekValue;
        this.sound.seek(seekingTo, this.id);
    }
    public get seek(): number {
        if (!this.isValidInstance()) {
            return 0;
        }
        const currentSeek = this.sound.seek(this.id);
        const tweakedSeek = Math.max(0, (currentSeek - this.soundStart));
        return tweakedSeek;
    }

    public set loop(value: boolean) {
        if (!this.isValidInstance()) {
            return;
        }
        this.sound.loop(value, this.id);
    }
    public get loop(): boolean {
        this.isValidInstance();
        const loopValue = this.sound.loop(this.id) as boolean;
        return loopValue;
    }

    public pause(): void {
        if (!this.isValidInstance()) {
            return;
        }
        this.sound.pause(this.id);
        this.clearTimeout();
    }
    public resume(): void {
        if (!this.isValidInstance()) {
            return;
        }
        this.sound.play(this.id);
        this.clearTimeout();
    }

    public get isPlaying(): boolean {
        return this.sound.isLoaded && this.sound.playing(this.id);
    }

    public stop(): void {
        this.clearTimeout();
        if (!this.isDisposed || this.isPlaying) {
            this.sound.stop(this.id);
        }
    }

    protected delayPlay(delayInMs: number): void {
        this.delayTimeoutId = window.setTimeout(() => {
            this.resume();
        }, delayInMs);
    }

    protected clearTimeout(): void {
        if (this.delayTimeoutId !== undefined) {
            window.clearTimeout(this.delayTimeoutId);
            this.delayTimeoutId = undefined;
        }
    }

    protected setupHowlListeners(): void {
        this.sound.on('volume', () => {
            if (this.isDisposed) {
                return;
            }
            this.emit('volume', this.volume);
        }, this.id);
        this.sound.on('stop', () => {
            this.emit('stop');
        }, this.id);
        this.sound.on('seek', () => {
            if (this.isDisposed) {
                return;
            }
            this.emit('seek', this.seek);
        }, this.id);
        this.sound.on('rate', () => {
            if (this.isDisposed) {
                return;
            }
            this.emit('rate', this.rate);
        }, this.id);
        this.sound.on('play', () => {
            this.emit('play');
        }, this.id);
        this.sound.on('pause', () => {
            this.emit('pause');
        }, this.id);
        this.sound.on('mute', () => {
            this.emit('mute', this.isMuted);
        }, this.id);
        this.sound.on('fade', () => {
            if (this.isDisposed) {
                return;
            }
            this.emit('fade', this.volume);
        }, this.id);
        this.sound.on('end', () => {
            this.emit('end');
        }, this.id);
    }

    protected get instanceExists(): boolean {
        return this.sound.isLoaded && this.id > -1;
    }

    protected isValidInstance(): boolean {
        if (!this.instanceExists || this.isDisposed) {
            const soundName = this.sprite ? `${this.sound.name} - ${this.sprite}` : this.sound.name;
            logAudioError(`Sound instance (${soundName}) [${this.id}] has been disposed`);
            return false;
        }
        return true;
    }

    public dispose(): void {
        if (this.disposed) {
            return;
        }
        this.disposed = true;
        this.stop();
        this.sound.off('end', this.id);
        this.sound.off('volume', this.id);
        this.sound.off('stop', this.id);
        this.sound.off('seek', this.id);
        this.sound.off('rate', this.id);
        this.sound.off('play', this.id);
        this.sound.off('pause', this.id);
        this.sound.off('mute', this.id);
        this.sound.off('fade', this.id);
        this.emit('dispose', this.id);
        this.removeAllListeners();
    }
}